      '<section class="exec-panel">'+heading('Recebimento por fornecedor · '+scope.period,'USD',info(cashCriteria+' '+scope.detail),'Status pagamento: Pago · Data de compensação')+ranking(safeList(model.suppliers),'received',{title:'Recebido',detailKind:'receipt',totalAmount:report.meta?.totals?.received??sum(receipts,'received'),totalRows:safeList(report.receiptRows).map(row=>row.row),totalUnit:'pagamentos'})+sourceFoot('RECEBIMENTO')+'</section></div></div>';
