  function onChange(event){if(['executiveYear','executiveClaimYear'].includes(event.target.id))referenceYear=Number(event.target.value);else if(['executiveMonth','executiveClaimMonth'].includes(event.target.id))referenceMonth=Number(event.target.value);else return;render(model);if(claimsHost)renderClaims(model,claimsHost);}
  function onClick(event){const trigger=event.target.closest('[data-exec-detail]');if(trigger&&detailItems.has(trigger.dataset.execDetail))showDetail(detailItems.get(trigger.dataset.execDetail));}
  function detailRows(item){
    const source=item.kind==='receipt'?safeList(model.executiveReport.receiptRows):item.kind==='open'?safeList(model.supplierOpenReport?.installments):item.kind==='case'?safeList(model.executiveReport.controlClaims):safeList(model.executiveReport.claimRows),wanted=new Set(item.rows.map(row=>typeof row==='object'?row.row:Number(row)));
    const rows=source.filter(row=>wanted.has(Number(row.row))),field=item.kind==='receipt'?'received':item.kind==='open'?'expected':item.kind==='claim'?'claimed':null;
    return field?rows.sort((a,b)=>{const first=number(a[field]),second=number(b[field]);return first==null?(second==null?0:1):second==null?-1:second-first||Number(a.row)-Number(b.row);}):rows;
  }
  function showDetail(item,refresh=false){
    const dialog=document.getElementById('detailDialog'),content=document.getElementById('detailContent'),title=document.getElementById('detailTitle');if(!dialog||!content||!title)return;
    const F=global.MinervaTableFilters;if(!refresh){F?.clearDetails?.('detail-exec-');activeDetail={item,rows:detailRows(item),query:'',tableId:'detail-exec-'+(++detailTableSequence)};}
    if(!activeDetail)return;
    if(!detailDialogs.has(dialog)){dialog.addEventListener?.('close',()=>{activeDetail=null;F?.close?.();F?.clearDetails?.('detail-exec-');});detailDialogs.add(dialog);}
    const state=activeDetail,receipt=item.kind==='receipt',open=item.kind==='open',caseDetail=item.kind==='case',sla=['analysis','negotiation','opening'].includes(item.kind);title.textContent=item.title;
    const headers=receipt?['Linha Controle','Fornecedor','Setor','Referência','Compensação','Recebido USD']:open?['Linha Controle','Fornecedor','Referência','Status pagamento','Data prevista','Valor previsto USD']:sla?['Linha BD','SGR','Fornecedor','Situação','Data do evento',item.kind==='analysis'?'Índice SLA da base':'Dias informados']:caseDetail?['Linha BD','SGR','País','Fornecedor','Status','Situação','Motivo','Data RNC','Reclamado USD']:['Linha BD','SGR','País','Fornecedor','Situação','Motivo','Data RNC','Reclamado USD'];
    const cells=row=>receipt?[row.row,row.supplier,row.sector,row.reference,date(row.compDate),exact(row.received)]:open?[row.row,row.supplier,row.reference,row.status,date(row.dueDate),exact(row.expected)]:sla?[row.row,row.sgr,row.supplier,row.status,date(row[item.kind+'Event']?.date),item.kind==='analysis'?pct(row.analysisEvent?.value):days(row[item.kind+'Event']?.value)]:caseDetail?[row.row,row.sgr,row.country,row.supplier,row.caseStatus||'Não informado',row.status,row.reason,date(row.rncDate),exact(row.claimed)]:[row.row,row.sgr,row.country,row.supplier,row.status,row.reason,date(row.rncDate),exact(row.claimed)];
    const types=receipt||open||sla?['number','text','text','text','date','number']:caseDetail?['number','text','text','text','text','text','text','date','number']:['number','text','text','text','text','text','date','number'];
    const sortValues=row=>receipt?[row.row,row.supplier,row.sector,row.reference,row.compDate,number(row.received)]:open?[row.row,row.supplier,row.reference,row.status,row.dueDate,number(row.expected)]:sla?[row.row,row.sgr,row.supplier,row.status,row[item.kind+'Event']?.date,number(row[item.kind+'Event']?.value)]:caseDetail?[row.row,row.sgr,row.country,row.supplier,row.caseStatus||'Não informado',row.status,row.reason,row.rncDate,number(row.claimed)]:[row.row,row.sgr,row.country,row.supplier,row.status,row.reason,row.rncDate,number(row.claimed)];
    const searched=state.rows.filter(row=>searchKey(cells(row).join(' ')).includes(searchKey(state.query))),rows=F?F.prepare(state.tableId,headers,searched,row=>cells(row).map(esc),item.title,{types,sortValues}):searched;
    content.innerHTML='<div class="exec-detail-heading"><strong>'+esc(item.subtitle)+'</strong><span>'+integer(rows.length)+' de '+integer(state.rows.length)+' linhas</span></div><label class="exec-detail-search"><span>Buscar nas linhas</span><input id="executiveDetailSearch" type="search" value="'+esc(state.query)+'" placeholder="Fornecedor, referência ou situação" aria-label="Buscar no detalhe do indicador"></label>'+(F?F.summary(state.tableId):'')+'<div class="exec-detail-table"><table data-table-id="'+state.tableId+'"><thead><tr>'+headers.map((label,index)=>'<th scope="col" aria-sort="'+(F?.ariaSort(state.tableId,index)||'none')+'"'+(index===0||index===headers.length-1?' class="num"':'')+'>'+(F?F.heading(state.tableId,index,esc(label)):esc(label))+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+cells(row).map((value,index)=>'<td'+(index===0||index===headers.length-1?' class="exec-detail-number num"':'')+'>'+esc(value)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'+(!rows.length?empty('Nenhuma linha neste filtro'):'');
    content.querySelector('#executiveDetailSearch').addEventListener('input',event=>{state.query=event.target.value;const start=event.target.selectionStart,end=event.target.selectionEnd;showDetail(item,true);const input=content.querySelector('#executiveDetailSearch');input?.focus?.();if(Number.isInteger(start))input?.setSelectionRange?.(start,end);});
    if(!dialog.open)dialog.showModal();
  }
  function handlesTable(id){return typeof id==='string'&&id.startsWith('detail-exec-');}
  function handleFilter(id){if(activeDetail?.tableId===id)showDetail(activeDetail.item,true);}
  function worksheets(wb,worksheet){
    if(!model?.executiveReport||typeof worksheet!=='function')return;const report=model.executiveReport;
    worksheet(wb,'Executivo mensal',['Ano','Mês','Compensação','Recebido USD','Pagamentos'],safeList(report.monthlyReceipts).map(row=>[row.year,row.month,row.period,row.received,row.count]));
    if(report.negotiationPortfolio){const wanted=new Set(safeList(report.negotiationPortfolio.rows));worksheet(wb,'Carteira em negociação',['Linha BD','SGR','País','Fornecedor','Situação','Motivo','Data RNC','Reclamado USD'],safeList(report.claimRows).filter(row=>wanted.has(row.row)).sort((a,b)=>(b.claimed||0)-(a.claimed||0)).map(row=>[row.row,row.sgr,row.country,row.supplier,row.status,row.reason,row.rncDate,row.claimed]));}
    worksheet(wb,'Negociação por país',['País','Em negociação USD','Claims','Linhas BD'],safeList(report.negotiationPortfolio?.byCountry).map(row=>[row.country,row.amount,row.count,safeList(row.rows).join('; ')]));
    if(report.recoveryComparison){const c=report.recoveryComparison,claims=new Set(safeList(c.claimRows)),receipts=new Set(safeList(c.receiptRows));worksheet(wb,'Recuperação procedentes',['Período','Reclamado procedente USD','Recebido vinculado USD','Recuperação','Recebido fora da comparação USD'],[[scopeInfo(model).period,c.claimed,c.received,c.rate,c.unallocatedReceived]]);worksheet(wb,'Reclamado procedente',['Linha BD','SGR','Fornecedor','Situação','Data RNC','Reclamado USD'],safeList(report.claimRows).filter(row=>claims.has(row.row)).map(row=>[row.row,row.sgr,row.supplier,row.status,row.rncDate,row.claimed]));worksheet(wb,'Recebimentos procedentes',['Linha Controle','Fornecedor','Referência','Compensação','Recebido USD'],safeList(report.receiptRows).filter(row=>receipts.has(row.row)).map(row=>[row.row,row.supplier,row.reference,row.compDate,row.received]));}
    worksheet(wb,'Claims abertos por país',['País','Em negociação','Em análise','Aguardando custos','Total','Linhas BD'],safeList(report.openByCountry).map(row=>[row.country,row.negotiating,row.inAnalysis,row.awaitingCosts,row.total,safeList(row.rows).join('; ')]));
    worksheet(wb,'Recebido por setor',['Setor','Recebido USD','Pagamentos','Linhas Controle'],safeList(report.sectorReceipts).map(row=>[row.name,row.amount,row.count,safeList(row.rows).join('; ')]));
    worksheet(wb,'Motivos dos claims',['Motivo','Reclamado USD','Claims','Linhas BD'],safeList(report.reasonRanking).map(row=>[row.name,row.amount,row.count,safeList(row.rows).join('; ')]));
    worksheet(wb,'Causadores dos claims',['Causador','Reclamado USD','Claims','Linhas BD'],safeList(report.causeRanking).map(row=>[row.name,row.amount,row.count,safeList(row.rows).join('; ')]));
    worksheet(wb,'Prazos dos claims',['Período','SLA análise 25 dias %','Registros análise','Negociação dias','Registros negociação','Abertura dias','Registros abertura'],safeList(report.slaByMonth).map(row=>[row.period,row.analysisRate,row.analysisCount,row.negotiationDays,row.negotiationCount,row.openingDays,row.openingCount]));
  }
